/*
 * NETWORK_$GETHDR - get a page for building a packet header
 *
 * Original address: 0x00E0F37A
 * Size: 154 bytes (0x00E0F37A .. 0x00E0F413)
 * Generated by: Claude Opus 5.5
 *
 * Frame: (0x8,A6) node_ptr, (0xC,A6) va_out, (0x10,A6) pa_out.
 * A5 = the NETWORK segment (0xE248FC); the cells used are
 * NETWORK_$LOOPBACK_FLAG (+0x348), NETWORK_$HDR_PAGE_PA (+0x308) and
 * NETWORK_$HDR_PAGE (+0x30C).
 *
 * Blocks:
 *   0x00E0F38C-0x00E0F39E  loopback mode (flag negative) or a packet for
 *                          this node (*node_ptr == NODE_$ME): a private page
 *   0x00E0F3A0-0x00E0F3B8  WP_$CALLOC(&ppn, &status); *pa_out = ppn << 10
 *                          (the WP_$CALLOC status is not tested)
 *   0x00E0F3BA-0x00E0F3DC  NETBUF_$GETVA(pa, va_out, &status); a bad status
 *                          crashes the system
 *   0x00E0F3E0-0x00E0F3F6  otherwise the shared header page: take
 *                          ML_LOCK_NET_IO (0x18), *va_out = NETWORK_$HDR_PAGE,
 *                          *pa_out = NETWORK_$HDR_PAGE_PA
 *   0x00E0F3FA-0x00E0F404  if *va_out (re-read) is zero, give the lock back
 */

#include "network/network_internal.h"
#include "wp/wp.h"              /* WP_$CALLOC */
#include "netbuf/netbuf.h"      /* NETBUF_$GETVA */
#include "ml/ml.h"              /* ML_$LOCK, ML_$UNLOCK, ML_LOCK_NET_IO */
#include "node/node.h"          /* NODE_$ME */
#include "misc/crash_system.h"  /* CRASH_SYSTEM */

void NETWORK_$GETHDR(uint32_t *node_ptr, uint32_t *va_out, uint32_t *pa_out)
{
    uint32_t ppn;                       /* (-0x4,A6) */
    status_$t status;                   /* (-0x8,A6) */
    uint32_t pa;                        /* D0 */

    /* 0x00E0F38C-0x00E0F39E */
    if (NETWORK_$LOOPBACK_FLAG < 0 || *node_ptr == NODE_$ME) {
        /* 0x00E0F3A0-0x00E0F3B8 */
        WP_$CALLOC(&ppn, &status);
        pa = ppn << 10;
        *pa_out = pa;
        /* 0x00E0F3BA-0x00E0F3DC */
        NETBUF_$GETVA(pa, va_out, &status);
        if (status != status_$ok) {
            CRASH_SYSTEM(&status);
        }
    } else {
        /* 0x00E0F3E0-0x00E0F3F6 */
        ML_$LOCK(ML_LOCK_NET_IO);
        *va_out = NETWORK_$HDR_PAGE;
        *pa_out = NETWORK_$HDR_PAGE_PA;
        /* 0x00E0F3FA-0x00E0F404 */
        if (*va_out == 0) {
            ML_$UNLOCK(ML_LOCK_NET_IO);
        }
    }
}
